const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const sujet = String(j.subject || '');
  const de = String(typeof j.from === 'object' ? JSON.stringify(j.from) : (j.from || '')).toLowerCase();
  let source = null;
  if (sujet.includes('[BASSET]')) source = 'veille';
  else if (de.includes('chien.com') || de.includes('secondechance')) source = 'alerte';
  else if (de.includes('adoption.cso') || de.includes('presidentecso') || /coeur sous l.oreille/i.test(sujet)) source = 'association';
  else if (/basset/i.test(sujet)) source = 'autre';
  if (!source) continue;
  let texte = String(j.textPlain || '');
  if (!texte && j.textHtml) texte = String(j.textHtml).replace(/<a[^>]*href="([^"]+)"[^>]*>/gi, ' $1 ').replace(/<[^>]*>/g, ' ');
  texte = texte.replace(/\s+/g, ' ').trim().slice(0, 6000);
  out.push({ json: { source, sujet, de, texte } });
}
return out;

const proches = ['14','50','61','27','76','35','53','72','28','78','95','60','80'];
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const sources = $('Garder les mails basset').all();
let blocs = []; let nbAnnonces = 0; let assoc = false;
$input.all().forEach((it, i) => {
  const src = sources[i] ? sources[i].json : {};
  let brut = String(it.json.text || '').replace(/```json|```/g, '').trim();
  let r;
  try { r = JSON.parse(brut); } catch (e) { r = { pertinent: true, resume: brut.slice(0, 800), annonces: [], questions_association: [], action_suggeree: 'Réponse non structurée : relis le mail d origine dans le lab.' }; }
  if (src.source === 'association') assoc = true;
  if (!r.pertinent && src.source !== 'association') return;
  const annonces = (r.annonces || []).map(a => ({ ...a, proche: proches.includes(String(a.departement || '').trim()) }))
    .sort((a, b) => (b.proche - a.proche));
  nbAnnonces += annonces.length;
  let h = '<h3>' + (src.source === 'association' ? 'Message de l association' : 'Source : ' + esc(src.source)) + '</h3>';
  h += '<p><b>' + esc(src.sujet) + '</b><br>' + esc(r.resume) + '</p>';
  if (annonces.length) h += '<ul>' + annonces.map(a => '<li>' + (a.proche ? '📍 <b>Proche</b> – ' : '') + '<b>' + esc(a.nom) + '</b>, ' + esc(a.age) + ' – ' + esc(a.lieu) + ' ' + (a.departement ? '(' + esc(a.departement) + ')' : '') + ' ' + esc(a.pays) + '<br>Refuge : ' + esc(a.refuge) + ' – Compatibilité : ' + esc(a.compatibilite) + (a.lien ? '<br><a href="' + String(a.lien).replace(/"/g, '%22') + '">Voir l annonce</a>' : '') + '</li>').join('') + '</ul>';
  if ((r.questions_association || []).length) h += '<p><b>Questions posées :</b></p><ul>' + r.questions_association.map(q => '<li>' + esc(q) + '</li>').join('') + '</ul><p><i>Aucune réponse n a été envoyée : c est à toi de répondre.</i></p>';
  if (r.action_suggeree) h += '<p>➡️ ' + esc(r.action_suggeree) + '</p>';
  blocs.push(h);
});
if (!blocs.length) return [];
const sujet = assoc ? 'Basset : réponse de l association' : 'Basset : ' + nbAnnonces + ' mâle(s) à regarder';
const html = '<h2>Adoption basset</h2>' + blocs.join('<hr>') + '<p style="color:#888;font-size:12px">Tri automatique (Mistral). Vérifie toujours l annonce d origine.</p>';
return [{ json: { sujet, html } }];
